[{"order":1,"type":"heading","text":"Mockito: Mocking Objects, Stubbing Methods, Verifying Interactions"},{"order":2,"type":"paragraph","text":"Mockito is a popular open-source testing framework for Java. It allows you to create and configure mock objects. Mock objects simulate the behavior of real objects, allowing you to isolate the unit under test and verify its interactions with its dependencies. This tutorial will guide you through the core concepts of Mockito: mocking objects, stubbing methods, and verifying interactions."},{"order":3,"type":"subheading","text":"Setting up Mockito"},{"order":4,"type":"paragraph","text":"Before you start using Mockito, you need to add it to your project. If you are using Maven, add the following dependency to your `pom.xml` file:"},{"order":5,"type":"code","text":"<dependency>
    <groupId>org.mockito</groupId>
    <artifactId>mockito-core</artifactId>
    <version>5.10.0</version>
    <scope>test</scope>
</dependency>"},{"order":6,"type":"paragraph","text":"If you are using Gradle, add the following dependency to your `build.gradle` file:"},{"order":7,"type":"code","text":"dependencies {
    testImplementation 'org.mockito:mockito-core:5.10.0'
}"},{"order":8,"type":"subheading","text":"Mocking Objects"},{"order":9,"type":"paragraph","text":"Mocking an object involves creating a controlled substitute for a real object. Mockito provides several ways to create mock objects. The most common way is using the `@Mock` annotation or the `Mockito.mock()` method."},{"order":10,"type":"paragraph","text":"Example using `@Mock` annotation:"},{"order":11,"type":"code","text":"import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class ExampleTest {

    @Mock
    private MyService myService;

    @Test
    void testMyMethod() {
        // Stubbing the mock
        when(myService.getData()).thenReturn("Mocked Data");

        // Using the mock
        String data = myService.getData();
        assertEquals("Mocked Data", data);
    }
}

interface MyService {
    String getData();
}"},{"order":12,"type":"paragraph","text":"In the above example, `@ExtendWith(MockitoExtension.class)` initializes the mocks annotated with `@Mock`. `MyService` is an interface that is mocked."},{"order":13,"type":"paragraph","text":"Example using `Mockito.mock()` method:"},{"order":14,"type":"code","text":"import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.Mockito.when;

class ExampleTest {

    @Test
    void testMyMethod() {
        // Creating a mock
        MyService myService = Mockito.mock(MyService.class);

        // Stubbing the mock
        when(myService.getData()).thenReturn("Mocked Data");

        // Using the mock
        String data = myService.getData();
        assertEquals("Mocked Data", data);
    }
}

interface MyService {
    String getData();
}"},{"order":15,"type":"subheading","text":"Stubbing Methods"},{"order":16,"type":"paragraph","text":"Stubbing involves configuring the mock object to return specific values or throw exceptions when certain methods are called. This is done using the `when()` and `thenReturn()` methods (or `thenThrow()` for exceptions)."},{"order":17,"type":"paragraph","text":"Example of stubbing a method to return a value:"},{"order":18,"type":"code","text":"import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.Mockito.when;

class StubbingTest {

    @Test
    void testStubbing() {
        MyService myService = Mockito.mock(MyService.class);

        // Stubbing the getData() method to return "Stubbed Value"
        when(myService.getData()).thenReturn("Stubbed Value");

        String result = myService.getData();
        assertEquals("Stubbed Value", result);
    }
}

interface MyService {
    String getData();
}"},{"order":19,"type":"paragraph","text":"Example of stubbing a method to throw an exception:"},{"order":20,"type":"code","text":"import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.Mockito.when;

class StubbingExceptionTest {

    @Test
    void testStubbingException() {
        MyService myService = Mockito.mock(MyService.class);

        // Stubbing the getData() method to throw an exception
        when(myService.getData()).thenThrow(new RuntimeException("Simulated Exception"));

        assertThrows(RuntimeException.class, () -> myService.getData());
    }
}

interface MyService {
    String getData();
}"},{"order":21,"type":"paragraph","text":"You can also stub methods based on arguments passed to them using `Mockito.any()`, `Mockito.anyString()`, `Mockito.eq()`, etc."},{"order":22,"type":"code","text":"import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.when;

class StubbingWithArgumentsTest {

    @Test
    void testStubbingWithArguments() {
        MyService myService = Mockito.mock(MyService.class);

        // Stubbing the processData() method to return a specific value for any string argument
        when(myService.processData(anyString())).thenReturn("Processed: Any String");

        // Stubbing the processData() method to return a specific value for a specific string argument
        when(myService.processData("Specific Input")).thenReturn("Processed: Specific Input");

        String result1 = myService.processData("Some Input");
        String result2 = myService.processData("Specific Input");

        assertEquals("Processed: Any String", result1);
        assertEquals("Processed: Specific Input", result2);
    }
}

interface MyService {
    String processData(String input);
}"},{"order":23,"type":"subheading","text":"Verifying Interactions"},{"order":24,"type":"paragraph","text":"Verifying interactions ensures that the mock object's methods were called as expected. Mockito provides methods like `verify()` to check method invocations."},{"order":25,"type":"paragraph","text":"Example of verifying method invocations:"},{"order":26,"type":"code","text":"import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;

class VerificationTest {

    @Test
    void testVerification() {
        MyService myService = Mockito.mock(MyService.class);

        // Calling the method multiple times
        myService.getData();
        myService.getData();
        myService.getData();

        // Verify that getData() was called exactly 3 times
        verify(myService, times(3)).getData();

        // Verify that getData() was called at least once
        verify(myService).getData();
    }
}

interface MyService {
    String getData();
}"},{"order":27,"type":"paragraph","text":"You can also verify that a method was never called:"},{"order":28,"type":"code","text":"import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;

class NeverVerificationTest {

    @Test
    void testNeverVerification() {
        MyService myService = Mockito.mock(MyService.class);

        // Verify that getData() was never called
        verify(myService, never()).getData();
    }
}

interface MyService {
    String getData();
}"},{"order":29,"type":"paragraph","text":"You can also verify the order of method calls using `InOrder`:"},{"order":30,"type":"code","text":"import org.junit.jupiter.api.Test;
import org.mockito.Mockito;
import org.mockito.InOrder;

import static org.mockito.Mockito.inOrder;

class OrderVerificationTest {

    @Test
    void testOrderVerification() {
        MyService myService = Mockito.mock(MyService.class);

        myService.method1();
        myService.method2();

        InOrder inOrder = inOrder(myService);

        inOrder.verify(myService).method1();
        inOrder.verify(myService).method2();
    }
}

interface MyService {
    void method1();
    void method2();
}"},{"order":31,"type":"subheading","text":"Conclusion"},{"order":32,"type":"paragraph","text":"Mockito is a powerful tool for unit testing Java applications. By mocking dependencies, stubbing method calls, and verifying interactions, you can write more robust and maintainable tests. This tutorial covered the core concepts of Mockito, providing you with a solid foundation for using it in your projects. Explore the Mockito documentation for more advanced features and capabilities."}]
